def solve(s):
    toks = []
    i = 0
    while i < len(s):
        c = s[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            toks.append(int(s[i:j]))
            i = j
            continue
        toks.append(c)
        i += 1

    pos = [0]

    def peek():
        return toks[pos[0]] if pos[0] < len(toks) else None

    def expr():
        v = term()
        while peek() in ('+', '-'):
            op = toks[pos[0]]
            pos[0] += 1
            r = term()
            v = v + r if op == '+' else v - r
        return v

    def term():
        v = factor()
        while peek() in ('*', '/'):
            op = toks[pos[0]]
            pos[0] += 1
            r = factor()
            v = v * r if op == '*' else v // r
        return v

    def factor():
        t = peek()
        if t == '-':
            pos[0] += 1
            return -factor()
        if t == '+':
            pos[0] += 1
            return factor()
        if t == '(':
            pos[0] += 1
            v = expr()
            if peek() == ')':
                pos[0] += 1
            return v
        pos[0] += 1
        return t

    return expr()

def solve(text, k):
    counts = {}
    for w in text.split():
        w = w.lower().rstrip('.,!?;:')
        if not w:
            continue
        counts[w] = counts.get(w, 0) + 1
    items = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    return "\n".join("%s %d" % (w, c) for w, c in items[:k])

def solve(text):
    stats = {}
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        parts = line.split(None, 1)
        if not parts:
            continue
        level = parts[0]
        rest = parts[1] if len(parts) > 1 else ""
        comp = rest.split(":", 1)[0].strip()
        e, w = stats.get(comp, (0, 0))
        if level == "ERROR":
            e += 1
        elif level == "WARN":
            w += 1
        stats[comp] = (e, w)
    items = sorted(stats.items(), key=lambda kv: (-kv[1][0], -kv[1][1], kv[0]))
    return "\n".join("%s %d %d" % (c, e, w) for c, (e, w) in items)

LINES = [(0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6)]


def winner(b):
    for a, c, d in LINES:
        if b[a] != '.' and b[a] == b[c] == b[d]:
            return b[a]
    return None


def solve(board, side):
    other = 'O' if side == 'X' else 'X'
    memo = {}

    def score(b, turn):
        key = (b, turn)
        if key in memo:
            return memo[key]
        w = winner(b)
        if w == side:
            r = 1
        elif w == other:
            r = -1
        elif '.' not in b:
            r = 0
        else:
            vals = []
            for i, ch in enumerate(b):
                if ch == '.':
                    nb = b[:i] + turn + b[i+1:]
                    vals.append(score(nb, 'O' if turn == 'X' else 'X'))
            r = max(vals) if turn == side else min(vals)
        memo[key] = r
        return r

    best = None
    best_i = None
    for i, ch in enumerate(board):
        if ch == '.':
            nb = board[:i] + side + board[i+1:]
            v = score(nb, other)
            if best is None or v > best:
                best = v
                best_i = i
    return best_i

def solve(text):
    totals = {}
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        parts = [p.strip() for p in line.split(",")]
        if len(parts) < 3:
            continue
        dept = parts[1]
        totals[dept] = totals.get(dept, 0) + int(parts[2])
    items = sorted(totals.items(), key=lambda kv: (-kv[1], kv[0]))
    return "\n".join("%s %d" % (d, t) for d, t in items)

def solve(s):
    nums = [int(x) for x in s.split()]
    ivs = []
    for i in range(0, len(nums) - 1, 2):
        a, b = nums[i], nums[i + 1]
        ivs.append((min(a, b), max(a, b)))
    ivs.sort()
    out = []
    for lo, hi in ivs:
        if out and lo <= out[-1][1]:
            if hi > out[-1][1]:
                out[-1] = (out[-1][0], hi)
        else:
            out.append((lo, hi))
    return " ".join("%d-%d" % (a, b) for a, b in out)

import heapq


def solve(edges, start, goal):
    adj = {}
    for tok in edges.split():
        if not tok:
            continue
        pair, _, w = tok.partition(":")
        a, _, b = pair.partition("-")
        w = int(w)
        adj.setdefault(a, []).append((b, w))
        adj.setdefault(b, []).append((a, w))
    if start == goal:
        return 0
    dist = {start: 0}
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist.get(u, float('inf')):
            continue
        if u == goal:
            return d
        for v, w in adj.get(u, ()):
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return -1

def solve(text):
    balance = 0
    rejected = 0
    body = text.strip("\n")
    lines = body.split("\n") if body != "" else []
    for line in lines:
        parts = line.split()
        if len(parts) != 2 or parts[0] not in ("deposit", "withdraw"):
            rejected += 1
            continue
        word, amount = parts
        if not amount.isdigit() or int(amount) <= 0:
            rejected += 1
            continue
        n = int(amount)
        if word == "deposit":
            balance += n
        elif balance >= n:
            balance -= n
        else:
            rejected += 1
    return "%d %d" % (balance, rejected)
